def clean_tick_prices(prices, lower_bound, upper_bound):
    return [p for p in prices if lower_bound <= p <= upper_bound]

clean_tick_prices([10.0, 10.2, 99.9, 10.1, 0.1, 10.3], 9.0, 11.0)

def check_lookahead_leak(decision_date, data_available_date):
    return data_available_date > decision_date

check_lookahead_leak("2024-01-01", "2024-04-20")

def align_trading_calendar(full_calendar, raw_data_dict):
    result = []
    last_val = None
    for day in full_calendar:
        if day in raw_data_dict:
            last_val = raw_data_dict[day]
        result.append(last_val)
    return result

align_trading_calendar([1, 2, 3, 4], {1: 10.0, 3: 11.0})
